export const REQUIRED_DATA_CLAIM_IDS = USER_VISIBLE_DATA_CLAIMS.map(({ id }) => id) as readonly string[];
export function dataClaimById(id: string): UserVisibleDataClaim { const claim = USER_VISIBLE_DATA_CLAIMS.find((candidate) => candidate.id === id); if (!claim) throw new Error(`Missing data-claim audit entry: ${id}`); return claim; }
export function validateDataClaimAudit(claims = USER_VISIBLE_DATA_CLAIMS): void { const ids = new Set<string>(); for (const claim of claims) { if (!claim.id || ids.has(claim.id)) throw new Error(`Duplicate or empty data-claim id: ${claim.id}`); ids.add(claim.id); if (!DATA_CLAIM_CLASSIFICATIONS.includes(claim.classification) || !claim.source || !claim.contract || !claim.rationale || !claim.requiredDisposition) throw new Error(`Incomplete data-claim audit entry: ${claim.id}`); } }
